17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.api.OwnersApi;
32	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
33	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
34	import org.springframework.samples.petclinic.rest.dto.PetDto;
35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.util.UriComponentsBuilder;
44	
45	import jakarta.transaction.Transactional;
46	
47	/**
48	 * @author Vitaliy Fedoriv
49	 */
50	
51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        this.clinicService.saveOwner(owner);
107	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
108	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
109	            ownerMapper.membershipLevel(owner), ownerMapper.membershipNumber(owner));
110	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
111	        headers.setLocation(UriComponentsBuilder.newInstance()
112	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
113	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
119	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
120	        if (currentOwner == null) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        currentOwner.setAddress(ownerFieldsDto.getAddress());
124	        currentOwner.setCity(ownerFieldsDto.getCity());
125	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
126	        currentOwner.setLastName(ownerFieldsDto.getLastName());
127	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
128	        this.clinicService.saveOwner(currentOwner);
129	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Transactional
134	    @Override
135	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
136	        Owner owner = this.clinicService.findOwnerById(ownerId);
137	        if (owner == null) {
138	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
139	        }
140	        owner.setDeleted(true);
141	        this.clinicService.saveOwner(owner);
142	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
143	    }
144	
145	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
146	    @Override
147	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
148	        Owner owner = this.clinicService.findOwnerById(ownerId);
149	        if (owner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        HttpHeaders headers = new HttpHeaders();
153	        Pet pet = petMapper.toPet(petFieldsDto);
154	        owner.setId(ownerId);
155	        pet.setOwner(owner);
156	        pet.getType().setName(null);
157	        this.clinicService.savePet(pet);
158	        PetDto petDto = petMapper.toPetDto(pet);
159	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
160	            .buildAndExpand(pet.getId()).toUri());
161	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
167	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
168	        if (currentOwner != null) {
169	            Pet currentPet = this.clinicService.findPetById(petId);
170	            if (currentPet != null) {
171	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
172	                currentPet.setName(petFieldsDto.getName());
173	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
174	                this.clinicService.savePet(currentPet);
175	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
176	            }
177	        }
178	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
184	        HttpHeaders headers = new HttpHeaders();
185	        Visit visit = visitMapper.toVisit(visitFieldsDto);
186	        Pet pet = new Pet();
187	        pet.setId(petId);
188	        visit.setPet(pet);
189	        this.clinicService.saveVisit(visit);
190	        VisitDto visitDto = visitMapper.toVisitDto(visit);
191	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
192	            .buildAndExpand(visit.getId()).toUri());
193	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
194	    }
195	
196	
197	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
198	    @Override
199	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
200	        Owner owner = this.clinicService.findOwnerById(ownerId);
201	        if (owner != null) {
202	            Pet pet = owner.getPet(petId);
203	            if (pet != null) {
204	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
205	            }
206	        }
207	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
208	    }
209	}
