1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
13	
14	import java.util.Collection;
15	import java.util.List;
16	
17	/**
18	 * Maps Owner & OwnerDto using Mapstruct
19	 */
20	@Mapper(uses = PetMapper.class)
21	public interface OwnerMapper {
22	
23	    @Mapping(target = "displayName",
24	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
25	    @Mapping(target = "initials",
26	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
27	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
28	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
29	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
30	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
31	    @Mapping(target = "locality",
32	        expression = "java(org.springframework.samples.petclinic.util.CustomerCodes.regionOf(owner.getCustomerCode()))")
33	    @Mapping(target = "timezone",
34	        expression = "java(org.springframework.samples.petclinic.util.Localities.timezoneFor(org.springframework.samples.petclinic.util.CustomerCodes.regionOf(owner.getCustomerCode())))")
35	    @Mapping(target = "contactPreference",
36	        expression = "java(owner.getEmail() != null ? \"EMAIL\" : \"PHONE\")")
37	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
38	    @Mapping(target = "checkDigit",
39	        expression = "java(org.springframework.samples.petclinic.util.CheckDigits.luhn(owner.getCustomerCode()))")
40	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
41	    @Mapping(target = "possibleDuplicate", expression = "java(owner.getPossibleDuplicateOf() != null)")
42	    @Mapping(target = "telephoneDisplay",
43	        expression = "java(org.springframework.samples.petclinic.util.TelephoneFormatter.toDisplay(owner.getTelephone()))")
44	    @Mapping(target = "selfLink",
45	        expression = "java(owner.getId() == null ? null : \"/api/owners/\" + owner.getId())")
46	    OwnerDto toOwnerDto(Owner owner);
47	
48	    /** Age band derived from birthDate against registrationDate: MINOR (under 18), ADULT (18-64) or SENIOR (65+); null when birthDate is absent. */
49	    default String ageBand(Owner owner) {
50	        java.time.LocalDate birthDate = owner.getBirthDate();
51	        if (birthDate == null || owner.getRegistrationDate() == null) {
52	            return null;
53	        }
54	        int age = java.time.Period.between(birthDate, owner.getRegistrationDate()).getYears();
55	        if (age < 18) {
56	            return "MINOR";
57	        }
58	        return age < 65 ? "ADULT" : "SENIOR";
59	    }
60	
61	    /** The single duplicate-detection key: normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty). */
62	    default String identityKey(Owner owner) {
63	        return orEmpty(owner.getTelephone()) + '|' + orEmpty(owner.getEmail()) + '|' + orEmpty(owner.getHouseholdId());
64	    }
65	
66	    default String orEmpty(String value) {
67	        return value == null ? "" : value;
68	    }
69	
70	    /** Membership points: +2 for an email, +1 when namesakeCount is 0, +2 for a household of 3 or more, +3 for tenure over 365 days. */
71	    default int membershipPoints(Owner owner) {
72	        int points = 0;
73	        if (owner.getEmail() != null) {
74	            points += 2;
75	        }
76	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
77	            points += 1;
78	        }
79	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
80	            points += 2;
81	        }
82	        if (tenureFiscalYears(owner) >= 1) {
83	            points += 3;
84	        }
85	        return points;
86	    }
87	
88	    /** Numeric level derived from membershipPoints: 1 (0-1), 2 (2-3), 3 (4-5), 4 (6 or more). */
89	    default Integer membershipLevel(Owner owner) {
90	        int points = membershipPoints(owner);
91	        if (points <= 1) {
92	            return 1;
93	        }
94	        if (points <= 3) {
95	            return 2;
96	        }
97	        return points <= 5 ? 3 : 4;
98	    }
99	
100	    /** Fiscal years of tenure elapsed since registrationDate; 0 when the date is absent (a new owner has zero tenure). */
101	    default int tenureFiscalYears(Owner owner) {
102	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
103	        if (registrationDate == null) {
104	            return 0;
105	        }
106	        return org.springframework.samples.petclinic.util.FiscalYears.elapsed(registrationDate, java.time.LocalDate.now());
107	    }
108	
109	    /** The 'FY<YY>' fiscal year of the (business-day-adjusted) registrationDate; null when the date is absent. */
110	    default String fiscalYear(Owner owner) {
111	        return owner.getRegistrationDate() == null ? null
112	            : org.springframework.samples.petclinic.util.FiscalYears.label(owner.getRegistrationDate());
113	    }
114	
115	    /** Derive the '<customerCode>-M<YY>' membership number, where YY is the last two digits of the registrationDate fiscal year. */
116	    default String membershipNumber(Owner owner) {
117	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
118	            return null;
119	        }
120	        return String.format("%s-M%02d", owner.getCustomerCode(),
121	            org.springframework.samples.petclinic.util.FiscalYears.startYear(owner.getRegistrationDate()) % 100);
122	    }
123	
124	    Owner toOwner(OwnerDto ownerDto);
125	
126	    @Mapping(target = "id", ignore = true)
127	    @Mapping(target = "pets", ignore = true)
128	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
129	    @Mapping(target = "registrationDate", expression = "java(effectiveRegistrationDate(ownerDto))")
130	    @Mapping(target = "address", expression = "java(org.springframework.samples.petclinic.util.AddressNormalizer.compose(ownerDto.getAddressLine1(), ownerDto.getAddressLine2(), ownerDto.getAddress()))")
131	    Owner toOwner(OwnerFieldsDto ownerDto);
132	
133	    /** The supplied registration date, or today's date when absent, rolled forward off weekends to a business day. */
134	    default java.time.LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerDto) {
135	        java.time.LocalDate supplied = ownerDto.getRegistrationDate();
136	        return org.springframework.samples.petclinic.util.BusinessDays.toBusinessDay(
137	            supplied != null ? supplied : java.time.LocalDate.now());
138	    }
139	
140	    /** Normalize to E.164 so the create path stores, and duplicate detection compares, that form. */
141	    @Named("normalizeTelephone")
142	    default String normalizeTelephone(String telephone) {
143	        return TelephoneNormalizer.toE164(telephone);
144	    }
145	
146	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
147	
148	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
149	
150	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
151	        OwnerPageDto ownerPageDto = new OwnerPageDto();
152	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
153	        ownerPageDto.setPage(ownerPage.getNumber());
154	        ownerPageDto.setSize(ownerPage.getSize());
155	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
156	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
157	        return ownerPageDto;
158	    }
159	}
