287	    @Override
288	    public String toString() {
289	        return new ToStringCreator(this)
290	
291	            .append("id", this.getId())
292	            .append("new", this.isNew())
293	            .append("lastName", this.getLastName())
294	            .append("firstName", this.getFirstName())
295	            .append("address", this.address)
296	            .append("city", this.city)
297	            .append("telephone", this.telephone)
298	            .toString();
299	    }
300	}
