64	    @Override
65	    public Object afterBodyRead(Object body, HttpInputMessage inputMessage, MethodParameter parameter,
66	                                Type targetType, Class<? extends HttpMessageConverter<?>> converterType) {
67	        String telephone = ownerMapper.normalizeTelephone(((OwnerFieldsDto) body).getTelephone());
