17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.util.Collection;
22	import java.util.HashSet;
23	import java.util.Set;
24	
25	import org.springframework.samples.petclinic.model.Owner;
26	
27	/**
28	 * Builds and reads the {@code <REGION>-<HASH8>} owner customer code, where REGION is the
29	 * region resolved from the postcode and HASH8 is the first 8 upper-case hex characters of
30	 * SHA-256 over (normalizedTelephone + lastName).
31	 */
32	public final class CustomerCodes {
33	
34	    private CustomerCodes() {
35	    }
36	
37	    /** Build the {@code <REGION>-<HASH8>} code from the postcode region and the telephone+lastName hash. */
38	    public static String build(String city, String postcode, String telephone, String lastName) {
39	        return Localities.regionFor(city, postcode) + "-" + hash8(telephone + lastName);
40	    }
41	
42	    /**
43	     * Build the customer code, then de-duplicate it against {@code existingOwners} by appending
44	     * {@code -<n>} with the smallest {@code n >= 2} that makes it unique.
45	     */
46	    public static String buildUnique(String city, String postcode, String telephone, String lastName,
47	            Collection<Owner> existingOwners) {
48	        String base = build(city, postcode, telephone, lastName);
49	        Set<String> taken = new HashSet<>();
50	        for (Owner owner : existingOwners) {
51	            taken.add(owner.getCustomerCode());
52	        }
53	        String candidate = base;
54	        for (int n = 2; taken.contains(candidate); n++) {
55	            candidate = base + "-" + n;
56	        }
57	        return candidate;
58	    }
59	
60	    /** The region portion of a customer code (the text before the first {@code '-'}), or null when absent. */
61	    public static String regionOf(String customerCode) {
62	        if (customerCode == null) {
63	            return null;
64	        }
65	        int dash = customerCode.indexOf('-');
66	        return dash < 0 ? customerCode : customerCode.substring(0, dash);
67	    }
68	
69	    private static String hash8(String value) {
70	        try {
71	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
72	            return String.format("%02X%02X%02X%02X", digest[0], digest[1], digest[2], digest[3]);
73	        }
74	        catch (NoSuchAlgorithmException ex) {
75	            throw new IllegalStateException(ex);
76	        }
77	    }
78	}
