16	package org.springframework.samples.petclinic.util;
17	
18	import java.nio.charset.StandardCharsets;
19	import java.security.MessageDigest;
20	import java.security.NoSuchAlgorithmException;
21	import java.util.Collection;
22	import java.util.Locale;
23	
24	import org.springframework.samples.petclinic.model.Owner;
25	
26	/**
27	 * Deterministic household identity: the id is the first 12 hex characters of SHA-256 over
28	 * {@code normalizedLastName + '|' + postcode}, so owners with the same last name and postcode
29	 * share a household automatically.
30	 */
31	public final class Households {
32	
33	    private Households() {
34	    }
35	
36	    /** The deterministic householdId for the given last name and postcode. */
37	    public static String id(String lastName, String postcode) {
38	        String key = normalize(lastName) + '|' + (postcode == null ? "" : postcode);
39	        byte[] digest = sha256(key);
40	        StringBuilder hex = new StringBuilder(12);
41	        for (int i = 0; i < 6; i++) {
42	            hex.append(String.format("%02x", digest[i]));
43	        }
44	        return hex.toString();
45	    }
46	
47	    /** Whether any existing owner already belongs to the household identified by {@code householdId}. */
48	    public static boolean isDuplicate(Collection<Owner> existing, String householdId) {
49	        for (Owner other : existing) {
50	            if (householdId.equals(other.getHouseholdId())) {
51	                return true;
52	            }
53	        }
54	        return false;
55	    }
56	
57	    private static String normalize(String value) {
58	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
59	    }
60	
61	    private static byte[] sha256(String value) {
62	        try {
63	            return MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
64	        }
65	        catch (NoSuchAlgorithmException ex) {
66	            throw new IllegalStateException(ex);
67	        }
68	    }
69	}
