16	package org.springframework.samples.petclinic.util;
17	
18	import java.util.Map;
19	
20	/**
21	 * Resolves an owner's locality (region) from their city using a fixed lookup table.
22	 *
23	 * <p>The mapping is pinned to Sydney-&gt;NSW, Melbourne-&gt;VIC and Brisbane-&gt;QLD. Any
24	 * city outside the table resolves to {@code UNKNOWN}.
25	 */
26	public final class Localities {
27	
28	    private static final Map<String, String> CITY_REGION =
29	        Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
30	
31	    /** Region -> inclusive {low, high} 4-digit postcode range. */
32	    private static final Map<String, int[]> REGION_RANGE =
33	        Map.of("NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
34	
35	    /** Region -> IANA timezone name. */
36	    private static final Map<String, String> REGION_TIMEZONE =
37	        Map.of("NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
38	
39	    private Localities() {
40	    }
41	
42	    /** IANA timezone for {@code region} from the pinned table, or null when it is not one of NSW/VIC/QLD. */
43	    public static String timezoneFor(String region) {
44	        return REGION_TIMEZONE.get(region);
45	    }
46	
47	    /** Return the canonical region for {@code city}, or {@code UNKNOWN} when it is not in the table. */
48	    public static String regionFor(String city) {
49	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
50	    }
51	
52	    /** Prefer the region from the postcode range; fall back to the city table when the postcode is absent or unknown. */
53	    public static String regionFor(String city, String postcode) {
54	        String byPostcode = regionForPostcode(postcode);
55	        return byPostcode != null ? byPostcode : regionFor(city);
56	    }
57	
58	    /** Region whose range contains {@code postcode}, or {@code null} when it is absent, malformed, or out of every range. */
59	    private static String regionForPostcode(String postcode) {
60	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
61	            return null;
62	        }
63	        int value = Integer.parseInt(postcode);
64	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
65	            int[] range = entry.getValue();
66	            if (value >= range[0] && value <= range[1]) {
67	                return entry.getKey();
68	            }
69	        }
70	        return null;
71	    }
72	}
